
import json
import random
import secrets
import time

import streamlit as st
from google import genai
from google.genai import types, errors


# -------------------------------
# PAGE CONFIGURATION
# -------------------------------
st.set_page_config(
    page_title="AI Online Quiz and Assessment System",
    page_icon="📝",
    layout="centered"
)

st.title("📝 AI Online Quiz and Assessment System")
st.write(
    "Practice coding and aptitude questions generated by Gemini AI."
)


# -------------------------------
# GEMINI API CONFIGURATION
# -------------------------------
try:
    api_key = st.secrets["GEMINI_API_KEY"]
except (KeyError, FileNotFoundError):
    st.error(
        "Gemini API key is missing. Add GEMINI_API_KEY "
        "in Streamlit Secrets."
    )
    st.stop()

client = genai.Client(api_key=api_key)
MODEL_NAME = "gemini-3.8-flash"


# -------------------------------
# GENERATE QUESTIONS WITH RETRIES
# -------------------------------
def generate_questions(domain, difficulty, student_name):
    prompt = f"""
You are an expert quiz creator.

Create exactly 10 multiple-choice questions for an online assessment.

Student name: {student_name}
Domain: {domain}
Difficulty: {difficulty}

Requirements:
1. Generate 10 different questions.
2. Each question must have exactly 4 options.
3. There must be only one correct answer.
4. The answer must exactly match one of the four options.
5. Questions must be appropriate for the selected domain and difficulty.
6. Include a short explanation of the correct answer.
7. Include a topic for every question.
8. Vary the questions across different quiz attempts.
9. Do not include duplicate questions in this quiz.

Return ONLY valid JSON in this format:
{{
  "questions": [
    {{
      "question": "Question text",
      "options": [
        "Option A",
        "Option B",
        "Option C",
        "Option D"
      ],
      "answer": "Correct option text",
      "explanation": "Short explanation",
      "topic": "Topic name"
    }}
  ]
}}

Generate exactly 10 questions.
Quiz variation code: {secrets.token_hex(8)}
"""

    last_error = None

    # Retry temporary server errors up to 3 times.
    for attempt in range(3):
        try:
            response = client.models.generate_content(
                model=MODEL_NAME,
                contents=prompt,
                config=types.GenerateContentConfig(
                    response_mime_type="application/json",
                    temperature=0.9
                )
            )

            if not response.text:
                raise ValueError("Gemini returned an empty response.")

            data = json.loads(response.text)
            questions = data.get("questions", [])

            # Validate the generated questions.
            if len(questions) != 10:
                raise ValueError(
                    "The AI did not return exactly 10 questions. "
                    "Please generate the quiz again."
                )

            for question in questions:
                if not all(
                    key in question
                    for key in (
                        "question",
                        "options",
                        "answer",
                        "explanation",
                        "topic"
                    )
                ):
                    raise ValueError(
                        "A question is missing required information."
                    )

                if len(question["options"]) != 4:
                    raise ValueError(
                        "A question does not have exactly four options."
                    )

                if question["answer"] not in question["options"]:
                    raise ValueError(
                        "A correct answer does not match its options."
                    )

            return questions

        except errors.ServerError as exc:
            last_error = exc
            status_code = getattr(exc, "status_code", None)

            # Retry only temporary server errors.
            if status_code not in (500, 502, 503, 504):
                raise

            if attempt < 2:
                time.sleep(2 ** (attempt + 1))

        except (json.JSONDecodeError, ValueError):
            raise

    raise RuntimeError(
        "Gemini is temporarily unavailable. Please try again later."
    ) from last_error


# -------------------------------
# SESSION STATE
# -------------------------------
if "questions" not in st.session_state:
    st.session_state.questions = None

if "submitted" not in st.session_state:
    st.session_state.submitted = False

if "answers" not in st.session_state:
    st.session_state.answers = {}

if "student_name" not in st.session_state:
    st.session_state.student_name = ""


# -------------------------------
# STUDENT DETAILS AND QUIZ SETUP
# -------------------------------
st.subheader("1. Student Details")

student_name = st.text_input(
    "Enter your name",
    value=st.session_state.student_name,
    placeholder="Enter your name"
)

st.subheader("2. Select Your Quiz")

domain = st.selectbox(
    "Choose a domain",
    [
        "Python",
        "Java",
        "SQL",
        "HTML/CSS",
        "JavaScript",
        "Aptitude"
    ]
)

difficulty = st.selectbox(
    "Choose difficulty",
    ["Easy", "Medium", "Hard", "Mixed"]
)

st.caption("Each quiz contains 10 AI-generated questions.")


# -------------------------------
# START NEW QUIZ
# -------------------------------
if st.button("Generate New Quiz", type="primary"):
    if not student_name.strip():
        st.warning("Please enter your name first.")
    else:
        st.session_state.questions = None
        st.session_state.submitted = False
        st.session_state.answers = {}
        st.session_state.student_name = student_name.strip()

        with st.spinner(
            "Gemini AI is generating your 10 questions..."
        ):
            try:
                questions = generate_questions(
                    domain,
                    difficulty,
                    student_name.strip()
                )

                random.shuffle(questions)

                # Shuffle the options without changing the answer.
                for question in questions:
                    random.shuffle(question["options"])

                st.session_state.questions = questions
                st.session_state.quiz_domain = domain
                st.session_state.quiz_difficulty = difficulty

                st.rerun()

            except Exception as exc:
                st.error(
                    "Could not generate the test. "
                    "Please try again after a short wait."
                )
                st.caption(f"Details: {exc}")


# -------------------------------
# DISPLAY QUESTIONS
# -------------------------------
if st.session_state.questions:
    questions = st.session_state.questions

    st.divider()
    st.subheader("3. Answer the Questions")

    st.write(
        f"**Student:** {st.session_state.student_name}"
    )
    st.write(
        f"**Domain:** {st.session_state.quiz_domain}"
    )
    st.write(
        f"**Difficulty:** {st.session_state.quiz_difficulty}"
    )

    if not st.session_state.submitted:
        with st.form("quiz_form"):
            selected_answers = {}

            for index, question in enumerate(questions):
                st.markdown(
                    f"**Question {index + 1}: "
                    f"{question['question']}**"
                )

                selected_answers[index] = st.radio(
                    "Select your answer:",
                    question["options"],
                    index=None,
                    key=f"answer_{index}",
                    label_visibility="collapsed"
                )

                st.caption(f"Topic: {question['topic']}")
                st.divider()

            submitted = st.form_submit_button(
                "Submit Quiz",
                type="primary"
            )

        if submitted:
            st.session_state.answers = selected_answers
            st.session_state.submitted = True
            st.rerun()

    # -------------------------------
    # RESULTS AND ANSWER REVIEW
    # -------------------------------
    if st.session_state.submitted:
        score = 0
        topic_results = {}

        for index, question in enumerate(questions):
            topic = question["topic"]

            if topic not in topic_results:
                topic_results[topic] = {
                    "correct": 0,
                    "total": 0
                }

            topic_results[topic]["total"] += 1

            selected = st.session_state.answers.get(index)

            if selected == question["answer"]:
                score += 1
                topic_results[topic]["correct"] += 1

        percentage = (score / len(questions)) * 100

        st.divider()
        st.subheader("4. Your Results")

        col1, col2, col3 = st.columns(3)

        col1.metric("Score", f"{score}/10")
        col2.metric("Percentage", f"{percentage:.1f}%")
        col3.metric("Correct Answers", score)

        if percentage >= 80:
            st.success("Excellent work! Keep practicing.")
        elif percentage >= 50:
            st.info("Good effort! Review the incorrect answers.")
        else:
            st.warning(
                "Keep practicing. Review the explanations below."
            )

        st.subheader("5. Answer Review")

        for index, question in enumerate(questions):
            selected = st.session_state.answers.get(index)
            correct_answer = question["answer"]

            st.markdown(
                f"**Question {index + 1}: "
                f"{question['question']}**"
            )

            st.write(
                f"Your answer: {selected if selected else 'Not answered'}"
            )
            st.write(f"Correct answer: {correct_answer}")

            if selected == correct_answer:
                st.success("Correct answer")
            else:
                st.error("Incorrect answer")

            st.write(
                f"**Explanation:** {question['explanation']}"
            )
            st.caption(f"Topic: {question['topic']}")
            st.divider()

        # -------------------------------
        # TOPIC-WISE IMPROVEMENT
        # -------------------------------
        st.subheader("6. Topics to Improve")

        weak_topics = [
            topic
            for topic, result in topic_results.items()
            if result["correct"] < result["total"]
        ]

        if weak_topics:
            st.write(
                "Review these topics and practice more questions:"
            )

            for topic in weak_topics:
                result = topic_results[topic]
                st.write(
                    f"- **{topic}:** "
                    f"{result['correct']}/{result['total']} correct"
                )
        else:
            st.success(
                "Perfect score! You answered every question correctly."
            )

        st.subheader("Topic Performance")

        for topic, result in topic_results.items():
            topic_percentage = (
                result["correct"] / result["total"]
            ) * 100

            st.write(
                f"**{topic}:** {result['correct']}/"
                f"{result['total']} ({topic_percentage:.0f}%)"
            )
            st.progress(int(topic_percentage))

        # -------------------------------
        # TAKE ANOTHER TEST
        # -------------------------------
        if st.button("Take Another Test"):
            st.session_state.questions = None
            st.session_state.submitted = False
            st.session_state.answers = {}
            st.rerun()
